PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS `balanceHistory` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`userId` integer NOT NULL,
	`portfolioId` integer NOT NULL,
	`totalValue` text NOT NULL,
	`cashValue` text NOT NULL,
	`investmentValue` text NOT NULL,
	`date` integer NOT NULL,
	"timestamp" integer NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `cashBalance` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`userId` integer NOT NULL,
	`portfolioId` integer NOT NULL,
	`amount` text NOT NULL,
	"createdAt" integer NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updatedAt" integer NOT NULL DEFAULT CURRENT_TIMESTAMP, "accountId" integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS `dividendHistory` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`userId` integer NOT NULL,
	`symbol` text NOT NULL,
	`dividendPerShare` text NOT NULL,
	`totalDividend` text NOT NULL,
	`exDate` integer NOT NULL,
	`paymentDate` integer,
	"createdAt" integer NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `etfHoldings` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`userId` integer NOT NULL,
	`portfolioId` integer NOT NULL,
	`symbol` text NOT NULL,
	`name` text NOT NULL,
	`quantity` text NOT NULL,
	`purchasePrice` text NOT NULL,
	`currentPrice` text NOT NULL,
	`purchaseDate` integer NOT NULL,
	"lastPriceUpdate" integer NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"createdAt" integer NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updatedAt" integer NOT NULL DEFAULT CURRENT_TIMESTAMP, `desiredAllocation` text DEFAULT '0' NOT NULL, "accountId" integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS `portfolios` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`userId` integer NOT NULL,
	`name` text NOT NULL,
	`description` text,
	"createdAt" integer NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updatedAt" integer NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `priceHistory` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`userId` integer NOT NULL,
	`symbol` text NOT NULL,
	`price` text NOT NULL,
	`date` integer NOT NULL,
	"timestamp" integer NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `purchases` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`userId` integer NOT NULL,
	`portfolioId` integer NOT NULL,
	`holdingId` integer NOT NULL,
	`symbol` text NOT NULL,
	`quantity` text NOT NULL,
	`price` text NOT NULL,
	`purchaseDate` integer NOT NULL,
	"createdAt" integer NOT NULL DEFAULT CURRENT_TIMESTAMP, "accountId" integer NOT NULL DEFAULT 0, `fees` text DEFAULT '0' NOT NULL, `cashTransactionId` integer, `isSold` integer DEFAULT false, `soldDate` integer);
CREATE TABLE IF NOT EXISTS `users` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`openId` text NOT NULL,
	`name` text,
	`email` text,
	`loginMethod` text,
	`role` text DEFAULT 'user' NOT NULL,
	"createdAt" integer NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updatedAt" integer NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"lastSignedIn" integer NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "__drizzle_migrations" (
			id SERIAL PRIMARY KEY,
			hash text NOT NULL,
			created_at numeric
		);
CREATE TABLE IF NOT EXISTS `accounts` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`userId` integer NOT NULL,
	`portfolioId` integer NOT NULL,
	`name` text NOT NULL,
	`number` text,
	"createdAt" integer NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"updatedAt" integer NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `cashBalanceHistory` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`userId` integer NOT NULL,
	`portfolioId` integer NOT NULL,
	`accountId` integer NOT NULL,
	`amount` text NOT NULL,
	"date" integer NOT NULL DEFAULT CURRENT_TIMESTAMP, `transactionType` text, `transactionAmount` text, `description` text);
CREATE TABLE IF NOT EXISTS `assetPrices` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`symbol` text NOT NULL,
	`price` text NOT NULL,
	`date` integer NOT NULL,
	`createdAt` integer DEFAULT CURRENT_TIMESTAMP NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX `users_openId_unique` ON `users` (`openId`);
COMMIT;
